using FluentValidation;

namespace HourBooking.Slices.Booking;

/// <summary>
/// Only the rules the request alone can settle, declared with enforce="periphery" on their GWT.
/// Everything else is a decision about accumulated state and lives in BookHoursEndpoint, where the
/// stream is visible — a state rule put in a validator is a rule that silently does not hold.
///
/// Note both of these still carry given="BookingMonthStarted" in the model. That is CONTEXT, not a
/// rule input, which is why where a rule is enforced had to be declared rather than derived.
/// </summary>
public sealed class BookHoursValidator : AbstractValidator<BookHours>
{
    public BookHoursValidator()
    {
        // HoursMustBeNonZero — "employees may never book 0 hours, so a HoursBooked with 0 hours
        // would be a business rule violation". Zero is not a booking; removal is the only way to
        // take a line back, which is why BookingRemoved exists as a distinct event.
        RuleFor(x => x.Hours)
            .GreaterThan(0m)
            .WithMessage("HoursMustBeNonZero");

        // HoursMustBeWholeOrHalf — "date + project + hours spend. Full hours or 0,5 hours."
        RuleFor(x => x.Hours)
            .Must(h => h % 0.5m == 0m)
            .WithMessage("HoursMustBeWholeOrHalf");
    }
}

